import{_ as e,o as t,c as i,ag as r}from"./chunks/framework.DMXcdKmJ.js";const c=JSON.parse('{"title":"使用工程 AI 技能","description":"在工程 AI 设置中查看、搜索和安装技能，管理模型可见状态，并核对更新与删除影响。","frontmatter":{"title":"使用工程 AI 技能","description":"在工程 AI 设置中查看、搜索和安装技能，管理模型可见状态，并核对更新与删除影响。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/guide/ai-skills.md","filePath":"zh/使用指南/使用工程AI技能.md"}'),o={name:"zh/guide/ai-skills.md"};function l(n,a,s,p,d,h){return t(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="使用工程-ai-技能" tabindex="-1">使用工程 AI 技能 <a class="header-anchor" href="#使用工程-ai-技能" aria-label="Permalink to &quot;使用工程 AI 技能&quot;">​</a></h1><p>技能是一组可复用的任务说明和相关资料，帮助 AI 按约定完成某类工作。它不是一个模型，也不会自动增加账号权限或保证生成结果正确。</p><p>工程技能由同工程成员共享。添加、更新或删除之前，先确认团队用途，优先采用组织认可的来源。</p><h2 id="_1-查看已有技能" tabindex="-1">1. 查看已有技能 <a class="header-anchor" href="#_1-查看已有技能" aria-label="Permalink to &quot;1. 查看已有技能&quot;">​</a></h2><p>进入工程“应用开发”的 AI 区域，打开 <strong>“设置” → “技能”</strong>。</p><p>从列表选择技能，查看名称、描述、来源、安装路径和说明内容。说明中有相关文档时可继续阅读，再返回上一级。</p><p>没有需要的技能并不影响普通 AI 对话；不要为了开始聊天先安装很多不熟悉的技能。</p><h2 id="_2-搜索和安装" tabindex="-1">2. 搜索和安装 <a class="header-anchor" href="#_2-搜索和安装" aria-label="Permalink to &quot;2. 搜索和安装&quot;">​</a></h2><ol><li>点击 <strong>“添加技能”</strong>，核对“保存到”的项目范围。</li><li>输入任务关键词并点击 <strong>“搜索”</strong>。</li><li>核对结果的来源、描述和要安装的技能，不只凭名字判断是否可信。</li><li>点击对应项的 <strong>“安装”</strong>，等待结束。</li><li>回到列表，确认已安装并能读取说明。</li></ol><p>技能安装在当前工程范围，由同工程成员共享，不用于给整个平台或其他工程统一安装。来源或网络不可用时先处理提示，不反复点击安装，也不换成未经审核的软件源。</p><p>技能可能包含指令、脚本或外部访问要求。使用前先查看内容，不因它出现在搜索结果中就交付密钥、允许设备操作或授权正式发布。</p><h2 id="_3-让当前对话使用技能" tabindex="-1">3. 让当前对话使用技能 <a class="header-anchor" href="#_3-让当前对话使用技能" aria-label="Permalink to &quot;3. 让当前对话使用技能&quot;">​</a></h2><p>安装或调整后，按页面提示 <strong>“重新加载会话”</strong>；需要明确使用某项技能时，在输入框输入 **<code>/</code>**查找当前可用的技能命令，选中后补充自己的任务。</p><p>技能实际是否适用，仍受当前模型、工具权限、工程资料和任务前提影响。没有看到命令时，先检查是否加载到当前工程，不编造技能名直接发送。</p><p>也可以在对话中说明要遵循哪项已存在的工程技能，并要求 AI 解释准备做什么，再确认执行范围。</p><h2 id="_4-管理可见状态与更新" tabindex="-1">4. 管理可见状态与更新 <a class="header-anchor" href="#_4-管理可见状态与更新" aria-label="Permalink to &quot;4. 管理可见状态与更新&quot;">​</a></h2><p>技能的开关管理它是否在模型提示词中可见，不等于删除技能文件。关闭时先阅读提示，核对当前需要的是隐藏提示、停止使用，还是实际删除。</p><p>“检查更新”用于核对可更新的安装项。更新前先确认团队正在使用的说明，更新后重新阅读变化、重新加载会话，并通过一个小任务核对效果，不直接让新版本处理正式设备或重要数据。</p><p>没有安装来源或不支持自动更新的项目，应按页面说明交由维护人员处理，不把“自动检查不可用”当作技能内容已经丢失。</p><h2 id="_5-删除要先确认" tabindex="-1">5. 删除要先确认 <a class="header-anchor" href="#_5-删除要先确认" aria-label="Permalink to &quot;5. 删除要先确认&quot;">​</a></h2><p>平台对工程来源的技能提供 <strong>“删除”</strong>。核对技能和工程后，确认删除提示；不确定时取消。</p><p>删除不可撤销，并会影响同工程后续使用。删除技能不会撤销此前 AI 已修改的源码或已执行的外部操作，也不等于删除相关对话。</p><h2 id="操作完成后检查什么" tabindex="-1">操作完成后检查什么 <a class="header-anchor" href="#操作完成后检查什么" aria-label="Permalink to &quot;操作完成后检查什么&quot;">​</a></h2><ul><li>列表和详情中的技能、来源与本次选择一致。</li><li>安装、更新、开关或删除的结果明确，刷新后仍符合预期。</li><li>需要时重新加载会话，核对命令或技能是否可用。</li><li>实际任务结果仍通过源码检查、预览和业务验证确认。</li></ul><p>下一步：<a href="/induframe-docs/zh/guide/ai-development.html">使用 AI 助手开发工程</a>，具体可用范围以 InduFrame 当前工程入口为准。</p>',25)])])}const u=e(o,[["render",l]]);export{c as __pageData,u as default};
